async ({ value }) => {
              const submitted = revision;
              const live = rail.terminals().find(candidate => candidate.incarnation === destination.object && candidate.id === id && candidate.running);

              if (!live || readOnly() || base !== nameFor(live)) {
                openRecovery(tab);

                return;
              }

              if (submitted && !(await drafts.submit(submitted))) {
                openRecovery(tab);

                return;
              }

              const failure = rename(live, value);

              if (submitted) drafts.settle(submitted, failure === null ? "acknowledged" : "failed");

              if (failure === null) clearItemFailure(live);
              else setFailure({ message: failure, terminal: live });

              if (failure !== null) openRecovery(tab);
            }

async (saved, refocus) => {
        setEditing(null);

        if (refocus) button?.focus();

        if (saved !== null && base === undefined) {
          recover(true);

          return;
        }

        if (saved !== null) {
          const submitted = revision;
          const failure = copyFailure();
          const expected = base;

          if (submitted && !(await drafts?.submit(submitted))) {
            recover(true);

            return;
          }

          void props.onRename(saved, expected).then(outcome => {
            if (submitted) drafts?.settle(submitted, outcome.status);

            if (outcome.status === "acknowledged" && copyFailure() === failure) failCopy(null);
          });
        }
      }

async (text, base, version) => {
                const result = await applying(() => connected.app.rpc("pad.rename", { name: base, newName: text, expectedIncarnation: version! }));

                if (result.kind === "refused") throw result.error;

                if (result.kind === "pending") setAsked(text);

                await useList.reload();
              }

async (path, name) => {
          setTabs(tabs().map(tab => tab.path === path ? { ...tab, name, base: name } : tab));

          return { path, name, revision: 0, status: "acknowledged", project: { path, name } };
        }

async auto => {
      if (pending()) return;
      const id = node().id;
      setPending(true);
      const message = await failureOf(() => connected.app.rpc("workstream.setAuto", { id, auto }));

      if (current()?.id === id) setFailure(message);
      setPending(false);
    }

async (text, base, version) => {
          if (todo) await applied(() => app.rpc("todo.update", { id: todo.id, title: text, body: null, expected_change: Number(version) }));
          else if (pad) await applied(() => app.rpc("pad.rename", { name: base, newName: text, expectedIncarnation: pad.incarnation }));
          else throw new Error(copy.railDraftMissingTarget);
        }

async () => {
      if (item() === "original" && failure === "read" && !fixed) throw new Error("opening refused");

      return item();
    }

latest = latest.then(work).then(
      () => {
        setFailure(null);
      },
      (error) => {
        if (!(error instanceof Error)) throw error;

        setFailure(error.message);
      },
    ).finally(() => {
      pending -= 1;

      if (pending === 0) apply(queued.splice(0));
    })

pending = pending.then(async () => {
      if (stopped) return;

      if (request.kind === "project") {
        await projects.open(request.path);

        return;
      }
      // Only link.read parses and authorizes the URL. A foreign Project cannot resolve
      // a same-named object; unopened Projects are never discovered from filesystem names.

      const surface = request.surface;
      const url = surface === undefined ? request.url : await inProject(app.forProject(surface), request.url);

      // The surface's own Project answers first, so a project-less link is read once, by its owner.
      const running = (await app.projects()).filter(project => project.running)
        .sort((a, b) => Number(b.path === surface) - Number(a.path === surface));

      const failures: string[] = [];

      for (const project of running) {
        try {
          const content = await app.forProject(project.path).rpc("link.read", { url });

          setLinked({ path: project.path, content, focus });
          fail(null);

          return;
        } catch (error) {
          if (!(error instanceof Error)) throw error;

          // Only the link's own Project names its cause; every other Project answers that it is not theirs.
          if (error instanceof RpcError && error.data?.kind === "other-project") continue;

          // U6249c3: the user cannot fix a link no Project can parse; the App log holds the cause.
          if (error instanceof RpcError && error.code === INVALID_PARAMS) {
            console.warn(linkCopy.notOpened(url, error.message));

            return;
          }

          failures.push(error.message);
        }
      }

      if (failures.length === 0) {
        const closed = offer ? await closedProject(url) : undefined;

        if (!closed) console.warn(linkCopy.notOpened(url, linkCopy.noOwner));
        else fail(linkCopy.closed(closed.name), { label: linkCopy.openProject(closed.name), run: () => void projects.open(closed.path).then(() => { fail(null); open(request, false); }) });
      } else fail([...new Set(failures)].join("; "));
    }).catch(error => { if (!(error instanceof Error)) throw error; fail(error.message); })
